INSERT INTO site_settings (id, page_meta, page_copy, page_assets, brand, hero, sections, contact) VALUES (1, '{"home":{"title":{"en":"Viral Zoom — Creative & Digital Agency","ar":"فايرال زوم — وكالة إبداعية ورقمية"},"description":{"en":"Creative ideas, digital marketing and production that help ambitious brands grow.","ar":"أفكار إبداعية وتسويق رقمي وإنتاج يساعد العلامات التجارية الطموحة على النمو."},"ogTitle":{"en":"Viral Zoom | Creative Digital Agency","ar":"فايرال زوم | وكالة إبداعية رقمية"},"ogDescription":{"en":"Strategy, design, marketing and production for brands ready to grow.","ar":"استراتيجية وتصميم وتسويق وإنتاج للعلامات التجارية المستعدة للنمو."}},"about":{"title":{"en":"About Viral Zoom — Creative Agency","ar":"من نحن — فايرال زوم"},"description":{"en":"Meet Viral Zoom, a creative and digital agency bringing strategy, design and technology together.","ar":"تعرف على فايرال زوم، وكالة إبداعية ورقمية تجمع الاستراتيجية والتصميم والتكنولوجيا."},"ogTitle":{"en":"About Viral Zoom","ar":"عن فايرال زوم"},"ogDescription":{"en":"A creative partner for brands ready to grow.","ar":"شريك إبداعي للعلامات التجارية المستعدة للنمو."}},"contact":{"title":{"en":"Contact Viral Zoom — Let''s Talk","ar":"تواصل مع فايرال زوم"},"description":{"en":"Have a project in mind? Get in touch with the Viral Zoom creative team.","ar":"عندك مشروع في بالك؟ تواصل مع فريق فايرال زوم الإبداعي."},"ogTitle":{"en":"Contact Viral Zoom","ar":"تواصل مع فايرال زوم"},"ogDescription":{"en":"Tell us what you are looking to create and let''s start a conversation.","ar":"احكيلنا عما تريد تنفيذه ولنبدأ الحوار."}},"services":{"title":{"en":"Our Services — Viral Zoom","ar":"خدمات فايرال زوم"},"description":{"en":"Explore the creative, digital marketing and production services offered by Viral Zoom.","ar":"اكتشف خدمات فايرال زوم الإبداعية والتسويقية والإنتاجية."},"ogTitle":{"en":"Viral Zoom Digital Marketing and Creative Services","ar":"خدمات التسويق الرقمي والإبداع من فايرال زوم"},"ogDescription":{"en":"Web design, digital marketing, social media and creative production.","ar":"تصميم مواقع وتسويق رقمي وإدارة سوشيال ميديا وإنتاج إبداعي."}},"projects":{"title":{"en":"Our Projects — Viral Zoom","ar":"أعمال فايرال زوم"},"description":{"en":"Explore Viral Zoom projects in social media, web design, apps and brand identity.","ar":"تصفح مشاريع فايرال زوم في السوشيال ميديا وتصميم المواقع والتطبيقات والهوية البصرية."},"ogTitle":{"en":"Viral Zoom Creative and Marketing Projects","ar":"أعمال فايرال زوم في التسويق والتصميم"},"ogDescription":{"en":"Selected social media, website, app and brand identity projects.","ar":"مشاريع مختارة في السوشيال ميديا والمواقع والتطبيقات والهوية البصرية."}}}', '{"ABOUT VIRAL ZOOM":{"en":"ABOUT VIRAL ZOOM","ar":"عن فايرال زوم"},"We turn bold ideas":{"en":"We turn bold ideas","ar":"نحوّل الأفكار"},"into real impact.":{"en":"into real impact.","ar":"الجريئة لتأثير حقيقي."},"We are a creative and digital agency bringing strategy, design and technology together to help brands move forward.":{"en":"We are a creative and digital agency bringing strategy, design and technology together to help brands move forward.","ar":"إحنا وكالة إبداعية ورقمية بنجمع الاستراتيجية والتصميم والتكنولوجيا عشان نساعد العلامات التجارية تتقدم."},"Get to know us":{"en":"Get to know us","ar":"اعرفنا أكتر"},"A creative digital project by Viral Zoom":{"en":"A creative digital project by Viral Zoom","ar":"مشروع رقمي إبداعي من فايرال زوم"},"Ideas made visible":{"en":"Ideas made visible","ar":"أفكار تتحول لواقع"},"WHO WE ARE":{"en":"WHO WE ARE","ar":"مين إحنا"},"A creative partner for brands ready to grow.":{"en":"A creative partner for brands ready to grow.","ar":"شريك إبداعي للعلامات اللي مستعدة تكبر."},"At Viral Zoom, we bring creative services and digital solutions together under one roof. From brand identity and content to websites, campaigns and production, we help shape consistent experiences that connect with people.":{"en":"At Viral Zoom, we bring creative services and digital solutions together under one roof. From brand identity and content to websites, campaigns and production, we help shape consistent experiences that connect with people.","ar":"في فايرال زوم، بنجمع الخدمات الإبداعية والحلول الرقمية في مكان واحد. من الهوية والمحتوى للمواقع والحملات والإنتاج، بنساعد في بناء تجارب متناسقة تقرّب علامتك من جمهورها."},"Every project starts with understanding what makes your business different. Then we turn that understanding into clear ideas, thoughtful design and work made to support your next step.":{"en":"Every project starts with understanding what makes your business different. Then we turn that understanding into clear ideas, thoughtful design and work made to support your next step.","ar":"كل مشروع بيبدأ بفهم اللي بيميّز شغلك. بعدها نحوّل الفهم لأفكار واضحة وتصميم مدروس وشغل يساعدك تاخد خطوتك الجاية."},"Explore selected projects":{"en":"Explore selected projects","ar":"شوف مشاريعنا"},"HOW WE THINK":{"en":"HOW WE THINK","ar":"طريقة تفكيرنا"},"Creative with purpose.":{"en":"Creative with purpose.","ar":"إبداع له هدف."},"Good work is more than a good-looking idea. It should make sense for your brand and move you toward a goal.":{"en":"Good work is more than a good-looking idea. It should make sense for your brand and move you toward a goal.","ar":"الشغل الحلو مش مجرد شكل جذاب؛ لازم يناسب علامتك ويقرّبك من هدفك."},"OUR APPROACH":{"en":"OUR APPROACH","ar":"منهجيتنا"},"Think clearly. Create boldly. Keep growing.":{"en":"Think clearly. Create boldly. Keep growing.","ar":"فكّر بوضوح. ابتكر بجرأة. واستمر في التطور."},"We work through a clear cycle: understand the opportunity, create and test ideas, learn from what happens, then build on what works.":{"en":"We work through a clear cycle: understand the opportunity, create and test ideas, learn from what happens, then build on what works.","ar":"بنتبع خطوات واضحة: نفهم الفرصة، نبتكر ونختبر الأفكار، نتعلم من النتائج، وبعدها نطوّر اللي أثبت نجاحه."},"LET''S BUILD WHAT''S NEXT":{"en":"LET''S BUILD WHAT''S NEXT","ar":"يلا نبدأ خطوتك الجاية"},"Have an idea in mind?":{"en":"Have an idea in mind?","ar":"عندك فكرة في بالك؟"},"Tell us what you are working toward. We would love to hear about it.":{"en":"Tell us what you are working toward. We would love to hear about it.","ar":"احكيلنا عن هدفك، ويسعدنا نسمع فكرتك."},"Start a conversation":{"en":"Start a conversation","ar":"ابدأ كلامنا"},"Start with insight":{"en":"Start with insight","ar":"نبدأ بالفهم"},"We learn about your brand, your audience and your goals before shaping the right direction.":{"en":"We learn about your brand, your audience and your goals before shaping the right direction.","ar":"نفهم علامتك وجمهورك وأهدافك قبل ما نحدد الاتجاه المناسب."},"Make ideas matter":{"en":"Make ideas matter","ar":"نحوّل الأفكار لتأثير"},"We bring creative thinking and practical strategy together to make every touchpoint count.":{"en":"We bring creative thinking and practical strategy together to make every touchpoint count.","ar":"نجمع بين الإبداع والاستراتيجية العملية عشان كل نقطة تواصل يكون ليها أثر."},"Build for progress":{"en":"Build for progress","ar":"نبني للتطور"},"We test, learn and refine the work, keeping the focus on meaningful progress for your brand.":{"en":"We test, learn and refine the work, keeping the focus on meaningful progress for your brand.","ar":"نختبر ونتعلم ونطوّر شغلنا، مع تركيزنا على تقدم حقيقي لعلامتك التجارية."},"New item":{"en":"New item","ar":"عنصر جديد"},"New post":{"en":"New post","ar":"منشور جديد"},"new followers":{"en":"new followers","ar":"متابع جديد"},"Creative digital work by Viral Zoom":{"en":"Creative digital work by Viral Zoom","ar":"أعمال رقمية إبداعية من فايرال زوم"},"LET''S MAKE SOMETHING GREAT":{"en":"LET''S MAKE SOMETHING GREAT","ar":"يلا نعمل حاجة مميزة"},"Let''s talk":{"en":"Let''s talk","ar":"خلّينا"},"about your next idea.":{"en":"about your next idea.","ar":"نتكلم عن فكرتك الجاية."},"A new project, a big idea or just a question — we''re ready to listen.":{"en":"A new 